import json,re,collections
R=json.load(open('nm/items.json')); V=json.load(open('nm/votes.json'))
SKIP=re.compile(r'APPROVAL OF (THE )?(SUMMARY )?MINUTES|PROCLAIM|RECOGNIZING|HONORING|CANVASS|APPOINTING|APPOINTMENT OF|CO-?DESIGNAT|DESIGNATING .{0,80}(STREET|AVENUE|WAY|DRIVE|BOULEVARD|DAY|MONTH|WEEK)|SETTING .{0,30}(DATE|TIME)|^\W*DISCUSSION|URGING|^SUPPORTING|OPPOSING|MOMENT OF SILENCE|CONDOLENCE|MILLAGE|TENTATIVE BUDGET|FINAL BUDGET|OPERATING BUDGET|BUDGET FOR FISCAL|AMENDED BUDGET|ELECTION|BALLOT|RECESS|RETIREMENT OF POLICE DOG|CITY-ISSUED FIREARM|SISTER CITY|GRANT APPLICATION|SUBMITTAL OF A? ?(GRANT )?APPLICATION|SUBMISSION OF (AN|A) (GRANT )?APPLICATION|MUTUAL AID|ADOPTING THE|CAPITAL IMPROVEMENT PLAN|LAW ENFORCEMENT TRUST FUND|COMPENSATION RATE|EMPLOYMENT AGREEMENT WITH THE CITY (MANAGER|ATTORNEY|CLERK)',re.I)
GOV=re.compile(r'^(THE )?(CITY|TOWN|VILLAGE|COUNTY|STATE|SCHOOL BOARD|MIAMI-DADE|FLORIDA (DEPARTMENT|DIVISION|HOUSING FINANCE|INTERNATIONAL UNIVERSITY BOARD|INLAND|OFFICE|FISH|COMMISSION)|UNITED STATES|U\.S\.|DEPARTMENT|NORTH MIAMI COMMUNITY REDEVELOPMENT|NORTH MIAMI CRA|CRA\b|SOUTH FLORIDA WATER|FEDERAL|OFFICE OF|NATIONAL OCEANIC|CHILDREN.S TRUST|THE CHILDREN|BROWARD|PALM BEACH|MONROE|NORTH MIAMI BEACH|BAL HARBOUR|AVENTURA|BISCAYNE PARK|EL PORTAL|SURFSIDE|GOLDEN BEACH|INDIAN CREEK|MIAMI SHORES|HIALEAH|OPA-LOCKA|MIAMI$)',re.I)
ENT=r"([A-Z0-9][A-Z0-9&.,'’\-/ ()]{2,120}?(?:,? (?:INC|LLC|L\.L\.C|CORP|CORPORATION|COMPANY|CO|P\.A|PA|LLP|PLLC|LTD|LLLP|LP|P\.C|N\.A|INCORPORATED)\b\.?|(?:UNIVERSITY|ASSOCIATION|FOUNDATION|CHURCH|MINISTRIES|ACADEMY|SCHOOL|CENTER|CLUB|SOCIETY|COUNCIL|INSTITUTE|ALLIANCE|PARTNERS|GROUP|BANK|TRUST|AUTHORITY)\b))"
def parties(t):
  out=[]
  for m in re.finditer(r'(?:BETWEEN THE CITY OF NORTH MIAMI(?: \(“?"?CITY"?”?\))?,? AND|BETWEEN THE CITY AND|SELECTION OF|AWARD(?:ING)? (?:OF )?(?:A |THE )?(?:CONTRACT |BID |AGREEMENT )?TO|PURCHASE ORDERS? (?:TO|FROM|WITH)|WITH|TO|AND|FROM|SELECTING|AGREEMENT WITH|RANKING|RANKED)\s+(?:THE FIRM OF |THE FIRMS OF |FIRMS )?'+ENT,t):
    p=m.group(1).strip(' ,.;')
    p=re.sub(r'^(THE|AN?|AND|WITH|TO|OF)\s+','',p)
    if len(p)<4 or GOV.match(p) or re.search(r'CITY OF NORTH MIAMI|NORTH MIAMI COMMUNITY REDEVELOPMENT|STATE OF FLORIDA|MIAMI-DADE COUNTY|DEPARTMENT OF|TREASURER|UNITED STATES|FLORIDA HOUSING|FLORIDA LEAGUE OF CITIES|SCHOOL BOARD|NATIONAL COOPERATIVE|COOPERATIVE PURCHASING|SOURCEWELL|OMNIA|NASPO|GSA|GENERAL SERVICES|SHERIFFS ASSOCIATION|PURCHASING COOP|CONTRACT NO|BID NO|RFP|RFQ|IFB|SOLICITATION|TERMS, CONDITIONS',p): continue
    p=re.sub(r'^.*\b(?:BETWEEN|AND|WITH|TO|OF|FROM)\s+(?=[A-Z])','',p) if len(p)>70 else p
    if p not in out: out.append(p)
  return out
KINDS=[('settlement',r'SETTLE'),('lease',r'\bLEASE|SUBLEASE|LICENSE AGREEMENT FOR (THE )?USE'),('sale',r'\bSALE OF|CONVEY(ANCE|ING)? .{0,40}TO|PURCHASE AND SALE AGREEMENT|DISPOSITION OF'),('zoning',r'SITE PLAN|CONDITIONAL USE|TENTATIVE PLAT|FINAL PLAT|WAIVER OF PLAT|VARIANCE|REZON|ZONING MAP|LAND USE PLAN AMENDMENT|FUTURE LAND USE MAP|DEVELOPMENT AGREEMENT|MASTER (CAMPUS )?DEVELOPMENT PLAN|SPECIAL EXCEPTION|ABANDONMENT|VACATION'),('easement',r'EASEMENT'),('grant',r'GRANT (FUNDS )?TO|AWARD OF .{0,60}(CDBG|HOME|SHIP|FUNDS) TO|SPONSORSHIP|FUNDING TO|DONATION TO|CONTRIBUTION TO|ALLOCATION .{0,40} TO'),('agreement',r'COLLECTIVE BARGAINING|MEMORANDUM OF UNDERSTANDING|BENEVOLENT|UNION|AFSCME|FRATERNAL ORDER|PARTNERSHIP|AGREEMENT'),('contract',r'PURCHASE|CONTRACT|BID|SERVICES|PIGGYBACK|RENEW|CHANGE ORDER|WORK ORDER|AMENDMENT')]
def kind(t):
  for k,p in KINDS:
    if re.search(p,t): return k
  return 'other'
def amount(t):
  a=[float(x.replace(',','')) for x in re.findall(r'\(\$\s?([\d,]+(?:\.\d\d)?)\)',t)]
  return max(a) if a else None
cand=[]
for i,r in enumerate(R):
  body=r['text']
  body=re.sub(r'^.*?(?=(?:A )?(?:PROPOSED )?(?:\(\w+ ?(?:READING|JUDICIAL)\) )?(?:RESOLUTION|ORDINANCE)\b(?! no))','',body,count=1,flags=re.S) if re.search(r'(RESOLUTION|ORDINANCE)\b(?! no)',body[:400]) else body
  body=re.sub(r'^\s*\[?\s*TAB\s+[A-Z]{1,2}\s*\]?\s*[–—\-:]*\s*(PASSED|Approved|CONTINUED|REMOVED|DEFERRED|PULLED|WITHDRAWN|TABLED|FAILED)?\s*[–—\-:]*\s*(Resolution\s*no\.?[^–—\-]*[–—\-]+|Ordinance\s*no\.?[^–—\-]*[–—\-]+)?\s*','',body,flags=re.I)
  body=re.sub(r'^(A )?(PROPOSED )?(\(\w+ ?(READING|JUDICIAL)\) )?(RESOLUTION|ORDINANCE)( \(\w+ READING\))?( FIRST READING| SECOND READING)? (OF THE )?(MAYOR AND )?CITY COUNCIL (AND )?(OF THE )?(OF THE )?CITY OF NORTH MIAMI,? (FLORIDA,? ?)?','',body)
  title=re.split(r'PROVIDING FOR (AN|THE)? ?EFFECTIVE DATE|PROVIDING AN EFFECTIVE DATE|PROVIDING FOR REPEAL',body)[0]
  if SKIP.search(title[:300]): continue
  ps=parties(title)
  k=kind(title)
  addr=re.findall(r'(?:LOCATED AT|AT) (\d{3,5}(?:-\d+)? (?:N\.?E\.?|N\.?W\.?|NE|NW|WEST|W\.|EAST|BISCAYNE|N\.)[^,;]{2,40})',title)
  cand.append({'i':i,'date':r['date'],'tab':r['tab'],'num':r['num'],'kind':k,'parties':ps,'addr':addr,'amount':amount(title),'title':re.sub(r'\s*(Tuesday|Monday|Wednesday|Thursday),? \w+ \d+, \d{4} Page \| \d+\s*',' ',title).strip(),'vote':V[i]})
json.dump(cand,open('nm/cand.json','w'),ensure_ascii=False)
print(len(cand),collections.Counter(c['kind'] for c in cand),collections.Counter(c['date'][:4] for c in cand))
